package com.gratilo.payment.service;
import io.micronaut.context.annotation.Value; import jakarta.inject.Singleton; import java.net.*; import java.net.http.*; import java.util.*; import java.util.regex.*;
@Singleton public class PoolDistributionClient { public record Member(UUID userId,String name,String email,double sharePercent){} public record Distribution(UUID poolId,String poolName,List<Member> members){} private final String base,key; private final boolean tipPoolsEnabled; public PoolDistributionClient(@Value("${pool.user-service-url:http://localhost:8081}")String base,@Value("${internal.api-key:local-internal-secret-change-me}")String key,@Value("${features.tip-pools-enabled:false}") boolean tipPoolsEnabled){this.base=base.replaceAll("/$","");this.key=key;this.tipPoolsEnabled=tipPoolsEnabled;} public Optional<Distribution> find(UUID owner){if(!tipPoolsEnabled)return Optional.empty();try{var response=HttpClient.newHttpClient().send(HttpRequest.newBuilder(URI.create(base+"/user-service/internal/pools/"+owner)).header("X-Internal-Secret",key).GET().build(),HttpResponse.BodyHandlers.ofString());if(response.statusCode()==404)return Optional.empty();if(response.statusCode()!=200)return Optional.of(new Distribution(null,null,List.of()));String json=response.body();String poolId=match(json,"\"poolId\"\s*:\s*\"([^\"]+)");String poolName=match(json,"\"poolName\"\s*:\s*\"([^\"]*)");var members=new ArrayList<Member>();var pattern=Pattern.compile("\"userId\"\s*:\s*\"([^\"]+)\".*?\"name\"\s*:\s*\"([^\"]*)\".*?\"email\"\s*:\s*\"([^\"]*)\".*?\"sharePercent\"\s*:\s*([0-9.]+)",Pattern.DOTALL);var m=pattern.matcher(json);while(m.find())members.add(new Member(UUID.fromString(m.group(1)),m.group(2),m.group(3),Double.parseDouble(m.group(4))));return poolId==null?Optional.of(new Distribution(null,null,List.of())):Optional.of(new Distribution(UUID.fromString(poolId),poolName,members));}catch(Exception ignored){return Optional.of(new Distribution(null,null,List.of()));}} private static String match(String value,String regex){var m=Pattern.compile(regex,Pattern.DOTALL).matcher(value);return m.find()?m.group(1):null;} }
